import { and, eq, isNull, sql } from \"drizzle-orm\";
import { newId } from \"@/lib/id\";
import { getDb, issueImports, issueLabels, issues, labels, members, users } from \"@/server/db\";
import { toIsoTimestamp } from \"@/types/common\";
import { toIssue } from \"./_mappers\";
import type { ImportIssuesInput } from \"@/schemas/issue-import\";
import type { IssueImportResult } from \"@/types/issue\";
import type { LabelId, OrgId, ProjectId, UserId } from \"@/types/common\";

export function findImport(orgId: OrgId, importKey: string): IssueImportResult | null {
  const row = getDb().select().from(issueImports).where(and(eq(issueImports.orgId, orgId), eq(issueImports.importKey, importKey))).get();
  return row ? { importKey, projectId: row.projectId as ProjectId, issues: JSON.parse(row.result), replayed: true } : null;
}

export function insertImport(input: ImportIssuesInput, authorId: UserId): IssueImportResult {
  return getDb().transaction((tx) => {
    const existing = tx.select().from(issueImports).where(and(eq(issueImports.orgId, input.orgId), eq(issueImports.importKey, input.importKey))).get();
    if (existing) return { importKey: input.importKey, projectId: existing.projectId as ProjectId, issues: JSON.parse(existing.result), replayed: true };
    const stamp = toIsoTimestamp(new Date());
    const max = tx.select({ value: sql<number | null>"'`max(${issues.number})` }).from(issues).where(and(eq(issues.orgId, input.orgId), eq(issues.projectId, input.projectId))).get();
    const memberRows = tx.select({ email: users.email, id: users.id }).from(members).innerJoin(users, eq(users.id, members.userId)).where(and(eq(members.orgId, input.orgId), eq(members.status, "active"), isNull(members.archivedAt))).all();
    const userByEmail = new Map(memberRows.map((member) => [member.email.toLowerCase(), member.id as UserId]));
    const labelRows = tx.select().from(labels).where(eq(labels.orgId, input.orgId)).all();
    const labelByName = new Map(labelRows.map((label) => [label.name, label.id as LabelId]));
    const imported = input.rows.map((item, index) => {
      const labelIds = [...new Set(item.labels)].map((name) => {
        let id = labelByName.get(name);
        if (!id) {
          id = newId() as LabelId;
          tx.insert(labels).values({ id, orgId: input.orgId, name, color: "#94a3b8", description: null, createdAt: stamp, updatedAt: stamp }).run();
          labelByName.set(name, id);
        }
        return id;
      });
      const row = tx.insert(issues).values({ id: newId(), orgId: input.orgId, projectId: input.projectId, number: (max?.value ?? 0) + index + 1, title: item.title, description: item.description, status: item.status, priority: item.priority, authorId, assigneeId: item.assigneeEmail ? userByEmail.get(item.assigneeEmail.toLowerCase()) ?? null : null, parentId: null, estimate: null, dueAt: item.dueAt, startedAt: null, completedAt: null, createdAt: stamp, updatedAt: stamp }).returning().get();
      if (labelIds.length) tx.insert(issueLabels).values(labelIds.map((labelId) => ({ orgId: input.orgId, issueId: row.id, labelId }))).run();
      return toIssue(row, labelIds);
    });
    tx.insert(issueImports).values({ orgId: input.orgId, importKey: input.importKey, projectId: input.projectId, result: JSON.stringify(imported) }).run();
    return { importKey: input.importKey, projectId: input.projectId, issues: imported, replayed: false };
  });
}
